"""The service's HTTP interface."""

import os
from typing import Annotated

from fastapi import Depends, FastAPI, Header, HTTPException, Response
from pydantic import BaseModel

from tasks_api.auth import get_current_user, signup_handler, signin_handler
from tasks_api.database import get_db, init_db
from tasks_api.models import HealthResponse, ItemCreate, ItemResponse, SignupRequest, SigninRequest

app = FastAPI(title="Tasks API")


@app.on_event("startup")
async def startup_event() -> None:
    """Initialize database and secret key on startup."""
    data_dir = os.environ.get("DATA_DIR", "data")
    os.makedirs(data_dir, exist_ok=True)

    secret_path = os.path.join(data_dir, "secret.key")
    if not os.path.exists(secret_path):
        import secrets
        new_key = secrets.token_hex(32)
        with open(secret_path, "w") as f:
            f.write(new_key)

    init_db()


@app.post("/signup", status_code=201)
async def signup(request: SignupRequest, db=Depends(get_db)) -> Response:
    return await signup_handler(request, db)


@app.post("/signin")
async def signin(request: SigninRequest, db=Depends(get_db)) -> Response:
    return await signin_handler(request, db)


@app.get("/items")
async def list_items(
    current_user: Annotated[int, Depends(get_current_user)],
    db=Depends(get_db),
) -> list[ItemResponse]:
    from tasks_api.database import list_items as get_items

    items = get_items(db, current_user)
    return [
        ItemResponse(id=item["id"], title=item["title"], done=item["done"])
        for item in items
    ]


@app.post("/items", status_code=201)
async def create_item(
    request: ItemCreate,
    current_user: Annotated[int, Depends(get_current_user)],
    db=Depends(get_db),
) -> ItemResponse:
    from tasks_api.database import create_item as db_create_item

    item_id = db_create_item(db, current_user, request.title)
    return ItemResponse(id=item_id, title=request.title, done=False)


class PatchRequest(BaseModel):
    done: bool


@app.patch("/items/{item_id}")
async def update_item(
    item_id: int,
    request: PatchRequest,
    current_user: Annotated[int, Depends(get_current_user)],
    db=Depends(get_db),
) -> ItemResponse:
    from tasks_api.database import update_item_done as db_update

    result = db_update(db, item_id, current_user, request.done)
    if result is None:
        raise HTTPException(status_code=404, detail="Item not found")
    return ItemResponse(id=result["id"], title=result["title"], done=result["done"])


@app.delete("/items/{item_id}", status_code=204)
async def delete_item(
    item_id: int,
    current_user: Annotated[int, Depends(get_current_user)],
    db=Depends(get_db),
) -> Response:
    from tasks_api.database import delete_item as db_delete

    deleted = db_delete(db, item_id, current_user)
    if not deleted:
        raise HTTPException(status_code=404, detail="Item not found")
    return Response(status_code=204)


@app.get("/health", response_model=HealthResponse)
def health() -> dict[str, str]:
    return {"status": "ok"}
